<?php
require '../config/config.php'; role(['administrator','pustakawan']);
if($_SERVER['REQUEST_METHOD']==='POST'){
  try{$uid=(int)($_POST['user_id']??0);if(!$uid)throw new Exception('Pilih anggota.');$pdo->prepare('INSERT INTO visits(user_id,visit_date,visit_time) VALUES(?,CURDATE(),CURTIME())')->execute([$uid]);setmsg('Kunjungan berhasil dicatat.');}catch(Throwable $e){setmsg($e->getMessage(),'danger');}
  header('Location:visits.php');exit;
}
$period=$_GET['period']??'month';$today=(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE visit_date=CURDATE()")->fetchColumn();$month=(int)$pdo->query("SELECT COUNT(*) FROM visits WHERE YEAR(visit_date)=YEAR(CURDATE()) AND MONTH(visit_date)=MONTH(CURDATE())")->fetchColumn();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');if($period==='today'){$from=$to=date('Y-m-d');}
$s=$pdo->prepare("SELECT v.*,u.name,u.username,u.class_name FROM visits v JOIN users u ON u.id=v.user_id WHERE v.visit_date BETWEEN ? AND ? ORDER BY v.visit_date DESC,v.visit_time DESC");$s->execute([$from,$to]);$rows=$s->fetchAll();
$members=$pdo->query("SELECT id,name,username,class_name FROM users WHERE role='anggota' AND status='aktif' ORDER BY name")->fetchAll();
?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Kunjungan Perpustakaan — SMPIT</title><link rel=stylesheet href="../public/style.css"><style>.visit-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:16px}.visit-stat{background:#fff;border:1px solid #e6edf7;border-radius:14px;padding:18px}.visit-stat .big{font-size:30px;font-weight:800;display:block;margin:5px 0}.visit-stat a{text-decoration:none;color:#075fd2;font-size:13px}@media(max-width:700px){.visit-stats{grid-template-columns:1fr}}</style></head><body><div class="layout"><?php include '../public/nav.php';?><main class="main"><h1>🚶 Kunjungan Perpustakaan</h1><?php msg()?><div class="visit-stats"><div class="visit-stat">📅 <b>Kunjungan Hari Ini</b><span class="big"><?=$today?></span><small>kunjungan tercatat hari ini</small><br><a href="?period=today">Tampilkan hari ini →</a></div><div class="visit-stat">🗓️ <b>Kunjungan Bulan Ini</b><span class="big"><?=$month?></span><small>kunjungan pada <?=date('F Y')?></small><br><a href="?period=month">Tampilkan bulan ini →</a></div><div class="visit-stat">👥 <b>Anggota Aktif</b><span class="big"><?=count($members)?></span><small>akun anggota aktif</small></div></div>
<div class="form"><h3>➕ Catat Kunjungan Anggota</h3><form method="post"><div class="grid"><div><label>Anggota</label><select name="user_id" required><option value="">Pilih anggota</option><?php foreach($members as $m):?><option value="<?=$m['id']?>"><?=e($m['name'].' — '.$m['username'].' — '.$m['class_name'])?></option><?php endforeach?></select></div><div style="display:flex;align-items:end"><button style="margin-bottom:10px">🚶 Catat Kunjungan Sekarang</button></div></div></form></div>
<br><div class="form"><h3>🔎 Filter Riwayat</h3><form method="get" class="grid"><div><label>Dari</label><input type="date" name="from" value="<?=e($from)?>"></div><div><label>Sampai</label><input type="date" name="to" value="<?=e($to)?>"></div><div><button>🔎 Tampilkan</button></div></form></div>
<br><div class="card"><h3>📋 Riwayat Kunjungan</h3><div class="table-wrap"><table class="table"><tr><th>No</th><th>Anggota</th><th>Kelas</th><th>Tanggal</th><th>Jam</th></tr><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><b><?=e($r['name'])?></b><br><small><?=e($r['username'])?></small></td><td><?=e($r['class_name']?:'-')?></td><td><?=e($r['visit_date'])?></td><td><?=e($r['visit_time'])?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="5">Tidak ada kunjungan pada periode tersebut.</td></tr><?php endif?></table></div></div></main></div></body></html>